        'Codex CLI Summary'
      );
      if (text.trim().length > 0) {
        console.log(`[LLMHelper] ✅ Codex CLI summary generated successfully.`);
        return this.processResponse(text);
      }
    } catch (e: any) {
      console.warn(`[LLMHelper] ⚠️ Codex CLI summary failed: ${e.message}. Falling back...`);
    }
